-- INSERT INTO `courses` VALUES ('1', 'Vue.js 从入门到精通', '深入学习 Vue.js，构建高效的前端应用', '1', '2024-12-03 10:19:41', null, '4.5', '编程开发', 'https://pic4.zhimg.com/v2-7755e6b9a5632e716bab5796110f7cbb_r.jpg', '199', '200', '2024年12月3日', 'Vue.js 是一款现代化的、渐进式的 JavaScript 框架，用于构建用户界面和单页应用程序（SPA）。它由尤雨溪（Evan You）创建，并作为开源项目发布。Vue.js 的设计核心是易用性、灵活性和高性能，同时具有轻量级、模块化和渐进增强的特点，使开发者能够根据项目需求自由选择功能。', null);
-- INSERT INTO `courses` VALUES ('2', 'React全栈开发实践', '掌握 React 及其生态系统，成为全栈开发者。', null, '2024-12-10 10:57:16', null, '4', '编程开发', 'https://img1.baidu.com/it/u=2493446131,1790798553&fm=253&fmt=auto&app=120&f=JPEG?w=800&h=500', '249', null, null, 'React全栈开发实践课程是一门综合性的前端技术培训课程，旨在帮助学员掌握使用React及相关技术栈进行全栈开发的能力。该课程从基础概念开始，逐步深入，确保每位同学都能跟上节奏，并通过实战导向和项目驱动的方式，培养真实的开发能力。课程内容涵盖了React简介与开发基础、组件、事件处理、条件渲染、列表、状态管理、表单以及组件的组合和继承等基础知识，同时还介绍了React Hooks、Context API、Redux等高级特性，以及React与不同后端技术（如Spring Boot、Python框架、Go）的整合开发。此外，课程还注重性能优化、调试工具的使用以及原生功能的集成，最终通过实际项目开发，让学员积累实战经验，提升职场竞争力。\r\n\r\n', null);
-- INSERT INTO `courses` VALUES ('3', 'Node.js后端开发', '掌握 Node.js 技术，构建高性能后端服务。', null, '2024-12-10 11:00:07', null, '4.5', '编程开发', 'https://img2.baidu.com/it/u=4152528325,3860350466&fm=253&fmt=auto?w=607&h=316', '229', null, null, 'Node.js后端开发课程是一门专注于使用Node.js进行服务器端开发的培训课程。该课程旨在帮助学员掌握Node.js的核心概念、搭建开发环境，并通过实际项目练习来提升后端开发技能。课程首先会介绍Node.js的基本概念和特性，包括异步编程、事件驱动模型等，这些是理解Node.js工作原理的关键。接着，学员将学习如何在计算机上安装Node.js和npm（Node Package Manager），这是Node.js的包管理器，用于管理项目的依赖。随后，课程会深入讲解Node.js的文件系统操作、网络编程以及数据库连接等内容。学员还将学习如何使用Express框架快速构建Web应用，并了解中间件的使用和路由的设计。此外，课程还会涉及RESTful API的开发、JWT认证、权限控制等高级主题。通过实战项目，学员将有机会将所学知识应用到实际开发中，从而积累宝贵的经验并提升职场竞争力。\r\n', null);
-- INSERT INTO `courses` VALUES ('4', 'Agular深入学习', '全面掌握 Angular 框架，开发复杂的企业级应用。', null, '2024-12-10 11:02:07', null, '4.5', '编程开发', 'https://img1.baidu.com/it/u=326381133,3642111611&fm=253&fmt=auto&app=138&f=GIF?w=1167&h=500', '239', null, null, 'Angular深入学习课程是一门专注于高级前端框架Angular的培训课程。该课程旨在帮助学员全面掌握Angular的核心概念和高级特性，并通过实际项目练习来提升开发技能。课程首先会介绍Angular的基本概念和特性，包括组件、服务、模块、数据绑定等。接着，学员将学习如何使用TypeScript进行强类型编程，并了解Angular的依赖注入机制和模板语法。随后，课程会深入讲解Angular的高级主题，如路由、表单处理、HTTP客户端服务以及测试和调试技巧。此外，课程还会涉及Angular Material等UI组件库的使用，以及性能优化和安全性等方面的知识。通过实战项目，学员将有机会将所学知识应用到实际开发中，从而积累宝贵的经验并提升职场竞争力。', null);
-- INSERT INTO `courses` VALUES ('5', '平面设计进阶', '深入学习平面设计，提升视觉传达能力。', null, '2024-12-10 11:03:59', null, '4.5', '设计艺术', 'https://img0.baidu.com/it/u=897236752,497029929&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=500', '179', null, null, '平面设计进阶课程是一门针对有一定基础的设计师或希望提升设计技能的学习者开设的高级培训课程。该课程旨在帮助学员掌握更复杂的设计理念和技术，提高设计作品的专业性和创新性。课程内容通常包括高级色彩理论、版式设计、字体设计、品牌设计、包装设计以及数字媒体设计等模块。学员将学习如何运用专业软件进行复杂图形和视觉效果的创建，同时也会接触到最新的设计趋势和技术。此外，课程还会强调创意思维的培养和设计流程的管理，使学员能够独立完成从概念到成品的整个设计过程。通过实际案例分析和项目实践，学员将有机会将所学知识应用到实际工作中，从而积累宝贵的经验并提升职场竞争力。', null);
-- INSERT INTO `courses` VALUES ('6', '色彩搭配原理', '了解色彩搭配的基本原理，提升审美能力。', null, '2024-12-10 11:05:38', null, '4.5', '设计艺术', 'https://img2.baidu.com/it/u=3249534045,2194576200&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1069', '129', null, null, '色彩搭配原理是一门研究如何将不同颜色组合在一起以创造和谐、美观和有效视觉效果的艺术。色相是颜色的分类，包括红、橙、黄、绿、蓝、紫等基本色。同色相搭配在一起通常更和谐，因为它们有相似的关键色调，这种搭配方式被称为单色调配。亮度是颜色的明暗程度，灰色是亮度中等的颜色。亮度差异较大的颜色搭配在一起会产生强烈的对比效果，而同亮度的颜色搭配则会产生柔和的效果。饱和度指的是颜色的纯度和强度，颜色越鲜艳，饱和度越高。适当搭配不同饱和度的颜色可以创造出丰富多彩的视觉效果。对比度是指两种或多种颜色在视觉上的差异。高对比度的色彩搭配可以产生强烈的视觉冲击，吸引注意力；低对比度的搭配则显得柔和、舒适。色彩的配比涉及到颜色之间的面积比例关系。合理的配比可以使设计更加平衡和协调。在对比色之间混入一些同样色相的色彩，以逐渐增加对比色色相之间的相似度，从而形成一种色素相同的调和美。同一种色彩在一件作品中出现两次或两次以上，以强调这种色彩之美。', null);
-- INSERT INTO `courses` VALUES ('7', '插画设计入门', '学习插画设计的基本技巧，创作独特作品', null, '2024-12-10 11:07:27', null, '4.8', '设计艺术', 'https://img0.baidu.com/it/u=3074601634,4119655757&fm=253&fmt=auto&app=138&f=JPEG?w=613&h=500', '129', null, null, '插画设计入门课程是一门专为初学者设计的培训课程，旨在帮助学员掌握插画设计的基本概念和技能。课程首先会介绍插画设计的基本概念，包括插画的定义、分类以及在各个领域的应用。接着，学员将学习到插画设计的基础知识，如色彩理论、构图原理、透视技巧等。这些知识是进行插画创作的基石，能够帮助学员理解如何通过色彩搭配、线条运用和空间布局来表达创意和情感。此外，课程还会教授学员如何使用各种绘画工具和软件，包括传统的画笔、颜料以及数字绘图板和专业绘图软件。通过实际操作，学员将学会如何将这些工具应用于创作中，从而更好地实现自己的设计理念。随着课程的深入，学员还将接触到更多高级的主题，如角色设计、场景构建、故事叙述等。这些内容不仅能够提升学员的创作能力，还能帮助他们开发出独特的个人风格。最终，通过实际项目练习和作品集的准备，学员将有机会将所学知识应用到实践中，积累宝贵的经验并提升职场竞争力。\r\n', null);
-- INSERT INTO `courses` VALUES ('8', '商务礼仪入门', '学习基本的商务礼仪，提高职场表现。', null, '2024-12-10 11:12:04', null, '4.5', '商业管理', 'https://img0.baidu.com/it/u=1219232109,2386761853&fm=253&fmt=auto&app=138&f=JPEG?w=888&h=500', '0', null, null, '商务礼仪是指在商务活动中，为了表示尊重、友好和专业，所遵循的一系列行为规范和礼节。它是商务交往中不可或缺的一部分，对于建立良好的商业关系、促进合作以及提升个人和企业形象都具有重要意义。在商务场合中，商务礼仪体现在多个方面。首先，着装得体是基本要求。男士应穿着整洁的西装，搭配合适的领带和皮鞋；女士则应选择端庄的职业装或套装，避免过于暴露或休闲的装扮。此外，个人卫生和仪表也是不可忽视的细节，如保持整洁的发型、修剪指甲等。其次，言谈举止要得体。在商务交流中，语言应清晰、准确、有礼貌，避免使用粗俗或冒犯性的言辞。同时，要注意倾听对方的意见，不打断别人讲话，展现出尊重和耐心。在举止方面，要保持端正的站姿和坐姿，避免做出不雅的动作或表情。此外，商务礼仪还包括一些具体的礼节和习惯。例如，在握手时，应使用适当的力度和时间，同时保持微笑和眼神交流；在交换名片时，应双手递送并接受对方的名片，以示尊重；在商务宴请中，要了解并遵守餐桌礼仪，如正确使用餐具、避免大声喧哗等。', null);
-- INSERT INTO `courses` VALUES ('9', '市场营销策略', '学习有效的市场营销策略，推动业务增长', null, '2024-12-10 11:14:58', null, '4.2', '商业管理', 'https://img2.baidu.com/it/u=2193841878,78003172&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=715', '149', null, null, '市场营销策略课程是一门专注于教授如何制定、实施和评估市场营销计划的高级培训课程。该课程旨在帮助学员掌握市场营销的核心概念、策略和工具，以便在竞争激烈的市场环境中取得成功。课程首先会介绍市场营销的基本概念和理论，包括市场细分、目标市场选择、定位以及营销组合（产品、价格、渠道和促销）等。学员将学习到如何通过市场调研来了解消费者需求和行为，从而为产品或服务制定合适的市场策略。接着，课程将深入探讨各种市场营销策略，如差异化营销、集中化营销、成本领先战略等。学员将了解到如何根据企业的实际情况和市场环境选择合适的策略，并通过案例分析来学习这些策略在实际中的应用。此外，课程还会教授学员如何使用各种市场营销工具和技术，包括数字营销、社交媒体营销、内容营销等。学员将学习到如何利用这些工具来提高品牌知名度、吸引潜在客户并促进销售。在课程的最后阶段，学员将有机会参与实际项目练习，将所学知识应用到实践中。他们将分组进行市场调研、制定营销计划并模拟实施，从而锻炼自己的实际操作能力和团队协作能力。', null);
-- INSERT INTO `courses` VALUES ('10', '财务管理实务', '学习财务管理知识，提高企业财务管理水平。', null, '2024-12-10 11:16:27', null, '4.4', '商业管理', 'https://img0.baidu.com/it/u=3893338343,2246997421&fm=253&fmt=auto&app=138&f=JPEG?w=750&h=500', '169', null, null, '财务管理实务课程是一门专注于教授如何进行企业财务管理的实际操作和策略制定的高级培训课程。该课程旨在帮助学员掌握财务管理的核心概念、方法和工具，以便在实际工作中做出明智的财务决策。课程首先会介绍财务管理的基本概念和原则，包括财务报表分析、资金筹集、投资决策、利润分配等。学员将学习到如何通过财务报表来评估企业的财务状况和经营成果，以及如何根据企业的战略目标制定合适的财务策略。接着，课程将深入探讨各种财务管理方法和技术，如预算编制、成本控制、现金流管理等。学员将了解到如何运用这些方法来优化企业的资源配置、提高运营效率并降低财务风险。此外，课程还会教授学员如何使用各种财务管理工具和软件，如Excel在财务管理中的应用、财务建模等。学员将学习到如何利用这些工具来进行财务预测、分析和决策支持。在课程的最后阶段，学员将有机会参与实际案例分析和项目练习，将所学知识应用到实践中。他们将分组进行财务分析、制定财务计划并模拟实施，从而锻炼自己的实际操作能力和团队协作能力。\r\n', null);
-- INSERT INTO `courses` VALUES ('11', '人力资源管理', '掌握人力资源管理的核心技能，提升团队效能', null, '2024-12-10 11:17:55', null, '4.3', '商业管理', 'https://img1.baidu.com/it/u=2878823939,1118358032&fm=253&fmt=auto&app=138&f=JPEG?w=751&h=500', '159', null, null, '人力资源管理课程是一门专注于教授如何进行企业人力资源管理的实际操作和策略制定的高级培训课程。该课程旨在帮助学员掌握人力资源管理的核心概念、方法和工具，以便在实际工作中做出有效的人力资源决策。课程首先会介绍人力资源管理的基本概念和原则，包括招聘与选拔、培训与发展、绩效管理、薪酬福利、劳动关系等。学员将学习到如何通过科学的人力资源管理来吸引、留住和激励员工，从而提高组织的整体绩效。接着，课程将深入探讨各种人力资源管理方法和技术，如人才测评、职业发展规划、员工关系管理等。学员将了解到如何运用这些方法来优化企业的人力资源配置、提高员工满意度并降低离职率。此外，课程还会教授学员如何使用各种人力资源管理工具和软件，如HR信息系统、在线招聘平台等。学员将学习到如何利用这些工具来提高人力资源管理的效率和准确性。在课程的最后阶段，学员将有机会参与实际案例分析和项目练习，将所学知识应用到实践中。他们将分组进行人力资源管理方案设计、实施并模拟评估效果，从而锻炼自己的实际操作能力和团队协作能力。', null);
-- INSERT INTO `courses` VALUES ('12', '英语口语速成课程', '提升您的英语口语能力，轻松应对各种场合', null, '2024-12-10 11:19:44', null, '4.4', '语言学习', 'https://img14.360buyimg.com/pop/jfs/t1/239173/13/14758/19320/66a4b790Fc5f41223/ef905630158036ac.jpg', '129', null, null, '英语口语速成课程是一门专为希望快速提高英语口语能力的学习者设计的培训课程。该课程旨在通过集中、高效的教学方法和实践活动，帮助学员在短时间内显著提升英语口语水平。课程首先会介绍英语口语的基本概念和技巧，包括发音、语调、连读、弱读等。学员将学习到如何正确发音和运用语调来表达不同的意思和情感。同时，课程还会教授一些常用的口语表达和句型，以便学员在实际交流中更加自然流畅。接着，课程将重点训练学员的听说能力。通过大量的听力练习和口语对话模拟，学员将逐渐适应并掌握英语口语的节奏和韵律。此外，课程还会提供丰富的话题和场景供学员进行讨论和实践，以增强他们的实际应用能力。为了加速学习进程，课程采用了多种教学手段和方法，如角色扮演、小组讨论、在线互动等。这些活动不仅能够帮助学员巩固所学知识，还能够激发他们的学习兴趣和积极性。在课程的最后阶段，学员将有机会参与实际的英语交流活动，如与外教进行一对一对话、参加英语角等。这些活动将为学员提供一个真实的语言环境，让他们在实践中不断提高自己的英语口语水平', null);
-- INSERT INTO `courses` VALUES ('13', '法语初级课程', '从零开始学法语，开启新的语言之旅', null, '2024-12-10 11:21:18', null, '4.1', '语言学习', 'http://t15.baidu.com/it/u=4202522106,3620860255&fm=224&app=112&f=JPEG?w=363&h=500', '119', null, null, '法语初级课程是一门专为初学者设计的培训课程，旨在帮助学员掌握法语的基本知识和技能。该课程通过系统的教学和实践活动，引导学员逐步进入法语世界，为进一步的学习打下坚实的基础。课程首先会介绍法语的基础知识，包括字母表、发音规则、基本词汇和常用短语。学员将学习到如何正确地发音和拼写法语单词，以及如何使用基本的语法结构来构建句子。此外，课程还会教授一些常用的问候语和日常用语，以便学员在实际交流中能够进行简单的沟通。接着，课程将重点训练学员的听说能力。通过大量的听力练习和口语对话模拟，学员将逐渐适应并掌握法语的语音和语调。同时，课程还会提供丰富的话题和场景供学员进行讨论和实践，以增强他们的实际应用能力。为了加速学习进程，课程采用了多种教学手段和方法，如角色扮演、小组讨论、在线互动等。这些活动不仅能够帮助学员巩固所学知识，还能够激发他们的学习兴趣和积极性。在课程的最后阶段，学员将有机会参与实际的法语交流活动，如与法语母语者进行对话、参加法语角等。这些活动将为学员提供一个真实的语言环境，让他们在实践中不断提高自己的法语水平', null);
-- INSERT INTO `courses` VALUES ('14', '西班牙语基础', '从零开始学西班牙语，拓展国际视野', null, '2024-12-10 11:23:24', null, '4.2', '语言学习', 'https://img0.baidu.com/it/u=825987743,3183129274&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=666', '109', null, null, '西班牙语基础课程是一门专为初学者设计的培训课程，旨在帮助学员掌握西班牙语的基本知识和技能。该课程通过系统的教学和实践活动，引导学员逐步进入西班牙语世界，为进一步的学习打下坚实的基础。课程首先会介绍西班牙语的基础知识，包括字母表、发音规则、基本词汇和常用短语。学员将学习到如何正确地发音和拼写西班牙语单词，以及如何使用基本的语法结构来构建句子。此外，课程还会教授一些常用的问候语和日常用语，以便学员在实际交流中能够进行简单的沟通。接着，课程将重点训练学员的听说能力。通过大量的听力练习和口语对话模拟，学员将逐渐适应并掌握西班牙语的语音和语调。同时，课程还会提供丰富的话题和场景供学员进行讨论和实践，以增强他们的实际应用能力。为了加速学习进程，课程采用了多种教学手段和方法，如角色扮演、小组讨论、在线互动等。这些活动不仅能够帮助学员巩固所学知识，还能够激发他们的学习兴趣和积极性。在课程的最后阶段，学员将有机会参与实际的西班牙语交流活动，如与西班牙语母语者进行对话、参加西班牙语角等。这些活动将为学员提供一个真实的语言环境，让他们在实践中不断提高自己的西班牙语水平', null);
-- INSERT INTO `courses` VALUES ('15', '日语初级课程', '从零开始学日语，体验日本文化', null, '2024-12-10 11:25:13', null, '4.2', '语言学习', 'https://img2.baidu.com/it/u=4026676352,434937153&fm=253&fmt=auto&app=138&f=JPEG?w=855&h=475', '119', null, null, '日语初级课程是一门专为初学者设计的培训课程，旨在帮助学员掌握日语的基本知识和技能。该课程通过系统的教学和实践活动，引导学员逐步进入日语世界，为进一步的学习打下坚实的基础。课程首先会介绍日语的基础知识，包括五十音图、发音规则、基本词汇和常用短语。学员将学习到如何正确地发音和书写日语假名，以及如何使用基本的语法结构来构建句子。此外，课程还会教授一些常用的问候语和日常用语，以便学员在实际交流中能够进行简单的沟通。接着，课程将重点训练学员的听说能力。通过大量的听力练习和口语对话模拟，学员将逐渐适应并掌握日语的语音和语调。同时，课程还会提供丰富的话题和场景供学员进行讨论和实践，以增强他们的实际应用能力。为了加速学习进程，课程采用了多种教学手段和方法，如角色扮演、小组讨论、在线互动等。这些活动不仅能够帮助学员巩固所学知识，还能够激发他们的学习兴趣和积极性。在课程的最后阶段，学员将有机会参与实际的日语交流活动，如与日语母语者进行对话、参加日语角等。这些活动将为学员提供一个真实的语言环境，让他们在实践中不断提高自己的日语水平', null);
-- INSERT INTO `courses` VALUES ('16', '摄影技巧大全', '从零开始学习摄影，拍出专业级照片', null, '2024-12-10 11:26:48', null, '4.3', '生活兴趣', 'https://img1.baidu.com/it/u=1073794756,1943950932&fm=253&fmt=auto&app=138&f=JPEG?w=889&h=500', '99', null, null, '摄影技巧大全课程是一门专为摄影爱好者和初学者设计的培训课程，旨在帮助学员全面掌握摄影的基本知识和技能。该课程通过系统的教学和实践活动，引导学员逐步进入摄影世界，为进一步的创作打下坚实的基础。课程首先会介绍摄影的基础知识，包括相机的种类和功能、镜头的选择和使用、曝光原理等。学员将学习到如何正确地操作相机，以及如何使用不同的镜头来拍摄不同类型的照片。此外，课程还会教授一些基本的构图原则和技巧，以便学员在实际拍摄中能够拍出更加美观和有趣的照片。接着，课程将重点训练学员的拍摄技巧。通过大量的实践练习和案例分析，学员将逐渐掌握不同场景下的拍摄方法和技巧。同时，课程还会提供丰富的话题和场景供学员进行讨论和实践，以增强他们的实际应用能力。为了加速学习进程，课程采用了多种教学手段和方法，如角色扮演、小组讨论、在线互动等。这些活动不仅能够帮助学员巩固所学知识，还能够激发他们的学习兴趣和积极性。在课程的最后阶段，学员将有机会参与实际的摄影创作活动，如主题摄影比赛、户外摄影采风等。这些活动将为学员提供一个真实的创作环境，让他们在实践中不断提高自己的摄影水平', null);
-- INSERT INTO `courses` VALUES ('17', '瑜伽基础教程', '学习瑜伽的基本动作，享受身心健康的乐趣', null, '2024-12-10 11:29:02', null, '4.3', '生活兴趣', 'https://img1.baidu.com/it/u=4273603161,4236907981&fm=253&fmt=auto&app=138&f=JPEG?w=440&h=309', '0', null, null, '瑜伽基础教程课程是一门专为初学者设计的培训课程，旨在帮助学员掌握瑜伽的基本知识和技能。该课程通过系统的教学和实践活动，引导学员逐步进入瑜伽世界，为进一步的练习打下坚实的基础。课程首先会介绍瑜伽的基础知识，包括瑜伽的起源、哲学思想、基本体式和呼吸法。学员将学习到如何正确地进行瑜伽体式的练习，以及如何配合呼吸来达到身心的平衡和放松。此外，课程还会教授一些基本的瑜伽冥想技巧，以便学员在练习中能够更好地集中注意力和放松身心。接着，课程将重点训练学员的瑜伽实践能力。通过大量的实践练习和案例分析，学员将逐渐掌握不同瑜伽体式的练习方法和技巧。同时，课程还会提供丰富的话题和场景供学员进行讨论和实践，以增强他们的实际应用能力。为了加速学习进程，课程采用了多种教学手段和方法，如角色扮演、小组讨论、在线互动等。这些活动不仅能够帮助学员巩固所学知识，还能够激发他们的学习兴趣和积极性。在课程的最后阶段，学员将有机会参与实际的瑜伽练习活动，如瑜伽工作坊、户外瑜伽练习等。这些活动将为学员提供一个真实的练习环境，让他们在实践中不断提高自己的瑜伽水平。', null);
-- INSERT INTO `courses` VALUES ('18', '烹饪技巧大全', '学习各种烹饪技巧，成为家庭大厨', null, '2024-12-10 11:30:30', null, '4.1', '生活兴趣', 'https://ss3.baidu.com/9fo3dSag_xI4khGko9WTAnF6hhy/baike/g=0;w=245/sign=e967ceec520fd9f9b01750625210e61e/ac6eddc451da81cb3b44625d5166d016082431fb.jpg', '89', null, null, '烹饪技巧大全课程是一门专为热爱烹饪和希望提高厨艺的学员设计的培训课程。该课程通过系统的教学和实践活动，引导学员掌握各种烹饪技巧和方法，从而能够独立完成美味佳肴的制作。课程首先会介绍烹饪的基础知识，包括食材的选择、处理和保存方法，以及厨房工具的使用和维护。学员将学习到如何正确地选择新鲜食材，以及如何使用不同的厨房工具来处理食材。此外，课程还会教授一些基本的烹饪术语和概念，以便学员在实际烹饪中能够更加准确地理解和操作。接着，课程将重点训练学员的烹饪技巧。通过大量的实践练习和案例分析，学员将逐渐掌握不同烹饪技巧和方法，如炒、煮、蒸、烤、炸等。同时，课程还会提供丰富的菜谱和配方供学员进行尝试和实践，以增强他们的实际应用能力。为了加速学习进程，课程采用了多种教学手段和方法，如角色扮演、小组讨论、在线互动等。这些活动不仅能够帮助学员巩固所学知识，还能够激发他们的学习兴趣和积极性。在课程的最后阶段，学员将有机会参与实际的烹饪创作活动，如主题烹饪比赛、家庭聚会菜单设计等。这些活动将为学员提供一个真实的创作环境，让他们在实践中不断提高自己的烹饪水平', null);
-- INSERT INTO `courses` VALUES ('19', '旅行摄影指南', '学习旅行摄影技巧，记录美好瞬间', null, '2024-12-10 11:31:23', null, '4.3', '生活兴趣', 'http://t15.baidu.com/it/u=3811460932,1907430082&fm=224&app=112&f=JPEG?w=500&h=500', '0', null, null, '旅行摄影指南课程是一门专为热爱旅行和摄影的学员设计的培训课程。该课程通过系统的教学和实践活动，引导学员掌握旅行摄影的基本知识和技能，从而能够在旅行中捕捉到美丽的瞬间和独特的风景。课程首先会介绍旅行摄影的基础知识，包括相机的选择和使用、镜头的种类和功能、曝光原理等。学员将学习到如何正确地操作相机，以及如何使用不同的镜头来拍摄不同类型的照片。此外，课程还会教授一些基本的构图原则和技巧，以便学员在实际拍摄中能够拍出更加美观和有趣的照片。接着，课程将重点训练学员的旅行摄影技巧。通过大量的实践练习和案例分析，学员将逐渐掌握不同场景下的拍摄方法和技巧，如风景、人物、建筑、夜景等。同时，课程还会提供丰富的话题和场景供学员进行讨论和实践，以增强他们的实际应用能力。为了加速学习进程，课程采用了多种教学手段和方法，如角色扮演、小组讨论、在线互动等。这些活动不仅能够帮助学员巩固所学知识，还能够激发他们的学习兴趣和积极性。在课程的最后阶段，学员将有机会参与实际的旅行摄影创作活动，如主题旅行摄影比赛、户外摄影采风等。这些活动将为学员提供一个真实的创作环境，让他们在实践中不断提高自己的旅行摄影水平', null);
-- INSERT INTO `courses` VALUES ('20', 'Python 编程入门', '了解 Python 编程的基础知识，适合初学者。', null, '2024-12-10 11:33:25', null, '4.8', '编程开发', 'https://img1.baidu.com/it/u=1626707091,1348276152&fm=253&fmt=auto&app=138&f=JPEG?w=752&h=500', '0', null, null, 'Python 是一种高级编程语言，设计简洁，易于学习和使用，适合从初学者到专业开发者。由 Guido van Rossum 于 1991 年创建，Python 强调可读性、代码简洁和开发效率，支持多种编程范式，如面向对象、函数式编程等。Python 拥有强大的标准库和丰富的第三方包，广泛应用于数据分析、人工智能、Web 开发、自动化脚本、科学计算等领域。', null);
-- INSERT INTO `courses` VALUES ('21', 'UI/UX 设计基础', '学习设计原则，打造优秀的用户体验', null, '2024-12-10 11:36:56', null, '4.2', '设计艺术', 'https://img1.baidu.com/it/u=1391535220,4183270843&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=500', '159', null, null, 'UI设计（用户界面设计）是指设计产品与用户之间交互的视觉界面，确保界面直观、易用且美观。它包括界面布局、色彩搭配、字体排版、图标设计和交互元素的设计，旨在提升用户体验，使用户能够高效、愉悦地操作产品。UI设计关注用户需求和视觉感受，是创造优秀数字产品的关键。', null);
-- INSERT INTO `courses` VALUES ('22', '绘画基础', '学习基本绘画技巧，激发您的艺术创造力。', null, '2024-12-10 11:41:09', null, '4.7', '设计艺术', 'http://t14.baidu.com/it/u=100951844,2643479799&fm=224&app=112&f=JPEG?w=500&h=500', '0', null, null, '绘画基础是一门旨在帮助学生掌握绘画基本技巧和理论的课程，适合初学者和有一定基础的学员。课程内容通常包括素描、色彩、构图、光影、透视等基础知识，强调观察能力、手眼协调及艺术感觉的培养。通过练习静物、人物、风景等不同题材，学生将逐步提高对形状、比例、空间和色彩的理解，学习如何表达自己的创意和情感。', null);
